import * as fs from 'fs'
import * as path from 'path'
import { commands, Uri, window, workspace } from 'vscode'

export type ToolKind = 'assembler' | 'emulator'

const isWindows = process.platform === 'win32'

// Platform specific defaults, used when the setting is left empty
const defaultTools: Record<ToolKind, string> = {
  assembler: isWindows ? 'BeebAsm.exe' : 'beebasm',
  emulator: isWindows ? 'BeebEm.exe' : 'b-em',
}

// The placeholder that is replaced by the disk image in beebvsc.emulatorArgs
export const DISK_IMAGE_PLACEHOLDER = '${diskImage}'

/**
 * Returns the configured executable for the given tool, or the platform
 * default if the setting is empty.
 */
export function getToolPath(kind: ToolKind, scope?: Uri): string {
  const value = workspace
    .getConfiguration('beebvsc', scope)
    .get<string>(kind)
    ?.trim()
  return value ? value : defaultTools[kind]
}

export const getAssemblerPath = (scope?: Uri) => getToolPath('assembler', scope)
export const getEmulatorPath = (scope?: Uri) => getToolPath('emulator', scope)

/**
 * Builds the emulator command line arguments for the given disk image.
 * If beebvsc.emulatorArgs does not contain ${diskImage}, the disk image is
 * appended as the last argument.
 */
export function getEmulatorArgs(diskImage: string, scope?: Uri): string[] {
  const configured =
    workspace
      .getConfiguration('beebvsc', scope)
      .get<string[]>('emulatorArgs') ?? []
  let replaced = false
  const args = configured.map((arg) => {
    if (arg.includes(DISK_IMAGE_PLACEHOLDER)) {
      replaced = true
      return arg.split(DISK_IMAGE_PLACEHOLDER).join(diskImage)
    }
    return arg
  })
  if (!replaced) {
    args.push(diskImage)
  }
  return args
}

/**
 * Locates an executable, either as a path (absolute or relative to cwd) or by
 * searching the PATH environment variable.
 * Returns the full path, or undefined if it could not be found.
 */
export function findExecutable(
  command: string,
  cwd?: string,
): string | undefined {
  const isFile = (file: string) => {
    try {
      return fs.statSync(file).isFile()
    } catch {
      return false
    }
  }
  const extensions = isWindows
    ? ['', ...(process.env.PATHEXT ?? '.EXE;.CMD;.BAT;.COM').split(';')]
    : ['']

  // An explicit path was given
  if (command.includes('/') || command.includes('\\')) {
    const full = path.isAbsolute(command)
      ? command
      : path.resolve(cwd ?? process.cwd(), command)
    return extensions.map((ext) => full + ext).find(isFile)
  }

  // Search the PATH
  const dirs = (process.env.PATH ?? '').split(path.delimiter).filter(Boolean)
  for (const dir of dirs) {
    for (const ext of extensions) {
      const candidate = path.join(dir, command + ext)
      if (isFile(candidate)) {
        return candidate
      }
    }
  }
  return undefined
}

// Only warn once per session for each missing tool, to avoid nagging
const warned = new Set<string>()

/**
 * Checks that the given tool can be found. If not, shows a single
 * non-modal warning offering to open the relevant setting.
 * Returns true if the tool was found.
 */
export function checkTool(kind: ToolKind, scope?: Uri, cwd?: string): boolean {
  const tool = getToolPath(kind, scope)
  if (findExecutable(tool, cwd) !== undefined) {
    return true
  }
  const key = `${kind}:${tool}`
  if (!warned.has(key)) {
    warned.add(key)
    const setting = `beebvsc.${kind}`
    window
      .showWarningMessage(
        `BeebVSC: could not find the ${kind} '${tool}'. Install it on your PATH, or set '${setting}' to its location.`,
        'Open Setting',
      )
      .then((choice) => {
        if (choice === 'Open Setting') {
          commands.executeCommand('workbench.action.openSettings', setting)
        }
      })
  }
  return false
}
